const BARE = /[A-Za-z0-9_-]/
const newTable = () => ({ t: 'table', m: new Map(), made: false })

function fail(msg) {
  throw new ParseError(msg)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  // at end of the directive: end of line or start of a comment
  atEnd() {
    return this.i >= this.s.length || this.s[this.i] === '#' || this.s[this.i] === ';'
  }
  peek() {
    return this.s[this.i]
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        break
      }
    }
    return names
  }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.s[this.i++]
      switch (e) {
        case '"': out += '"'; break
        case '\\': out += '\\'; break
        case 'n': out += '\n'; break
        case 't': out += '\t'; break
        case 'r': out += '\r'; break
        case '0': out += '\0'; break
        case 'u': {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
          break
        }
        default: {
          const ch = String.fromCodePoint(this.s.codePointAt(this.i - 1))
          fail('invalid escape \\' + ch)
        }
      }
    }
  }

  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }

  value(path) {
    this.ws()
    if (this.atEnd()) fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !/[ \t,\]};]/.test(this.s[this.i])) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true') return { t: 'boolean', v: true }
    if (tok === 'false') return { t: 'boolean', v: false }
    const run = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${run}$`).test(tok)) {
      return { t: 'integer', v: BigInt(tok.replace(/_/g, '').replace(/^\+/, '')) }
    }
    if (new RegExp(`^[+-]?${run}(?:\\.${run}(?:[eE][+-]?${run})?|[eE][+-]?${run})$`).test(tok)) {
      return { t: 'float', v: Number(tok.replace(/_/g, '')) }
    }
    fail('invalid value ' + tok)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        break
      }
      items.push(this.value(`${path}[${items.length}]`))
      this.ws()
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === ']') {
        this.i++
        break
      }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.peek() === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(path + '.' + names.join('.'))
      assign(tbl, path, names, v)
      this.ws()
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === '}') {
        this.i++
        break
      }
      fail('unterminated inline table')
    }
    return tbl
  }
}

const join = (base, names) => (base ? base + '.' : '') + names.join('.')

// Walk names through tables (and last elements of arrays of tables), creating tables.
function walk(tbl, base, names) {
  for (let k = 0; k < names.length; k++) {
    let c = tbl.m.get(names[k])
    if (c === undefined) {
      c = newTable()
      tbl.m.set(names[k], c)
    } else if (c.t === 'array' && c.aot) {
      c = c.items[c.items.length - 1]
    } else if (c.t !== 'table') {
      fail(`${join(base, names.slice(0, k + 1))} is not a table`)
    }
    tbl = c
  }
  return tbl
}

function assign(tbl, base, names, value) {
  const parent = walk(tbl, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (parent.m.has(last)) fail(`key ${join(base, names)} is defined twice`)
  parent.m.set(last, value)
}

export function parse(lines) {
  const root = newTable()
  let cur = root
  let curPath = ''
  lines.forEach((text, idx) => {
    try {
      const ln = new Line(text)
      ln.ws()
      if (ln.i >= text.length || text[ln.i] === '#' || text[ln.i] === ';') return
      if (text[ln.i] === '[') {
        ln.i++
        const aot = text[ln.i] === '['
        if (aot) ln.i++
        const names = ln.dotted()
        ln.ws()
        if (ln.peek() !== ']') fail('unterminated table header')
        ln.i++
        if (aot) {
          if (ln.peek() !== ']') fail('unterminated table header')
          ln.i++
        }
        ln.ws()
        if (!ln.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, '', names.slice(0, -1))
        const last = names[names.length - 1]
        const full = names.join('.')
        const ex = parent.m.get(last)
        if (aot) {
          if (ex === undefined) {
            cur = newTable()
            parent.m.set(last, { t: 'array', items: [cur], aot: true })
          } else if (ex.t === 'array' && ex.aot) {
            cur = newTable()
            ex.items.push(cur)
          } else fail(`${full} is not an array of tables`)
        } else if (ex === undefined) {
          cur = newTable()
          cur.made = true
          parent.m.set(last, cur)
        } else if (ex.t === 'table') {
          if (ex.made) fail(`table ${full} is defined twice`)
          ex.made = true
          cur = ex
        } else fail(`${full} is not a table`)
        curPath = full
        return
      }
      const names = ln.dotted()
      ln.ws()
      if (ln.peek() !== '=') fail('expected key = value')
      ln.i++
      const v = ln.value(join(curPath, names))
      ln.ws()
      if (!ln.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) throw new ParseError(`line ${idx + 1}: ${e.message}`)
      throw e
    }
  })
  return root
}
"}

